import{_ as n,a0 as d,w as u,s as a,ao as l,I as r,x as s,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse(`{"title":"Linux有问必答时间：怎样解决“XXX is not in the sudoers file”错误 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答时间：怎样解决“XXX is not in the sudoers file”错误 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答时间：怎样解决“XXX is not in the sudoers file”错误 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答时间：怎样解决“XXX is not in the sudoers file”错误 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20141224 Linux FAQs with Answers--How to fix 'XXX is not in the sudoers file' error","title":"Linux有问必答时间：怎样解决“XXX is not in the sudoers file”错误","tag":"201503","desc":""},"relativePath":"201503/20141224 Linux FAQs with Answers--How to fix 'XXX is not in the sudoers file' error.md","filePath":"[post].md"}`),p={name:"201503/20141224 Linux FAQs with Answers--How to fix 'XXX is not in the sudoers file' error.md"};function f(h,e,x,m,X,L){const o=d("Link");return u(),a("div",null,[e[11]||(e[11]=l(`<h1 id="linux有问必答时间-怎样解决-xxx-is-not-in-the-sudoers-file-错误" tabindex="-1">Linux有问必答时间：怎样解决“XXX is not in the sudoers file”错误 <a class="header-anchor" href="#linux有问必答时间-怎样解决-xxx-is-not-in-the-sudoers-file-错误" aria-label="Permalink to “Linux有问必答时间：怎样解决“XXX is not in the sudoers file”错误”">​</a></h1><blockquote><p><strong>问题</strong>:我想在我的Linux系统上使用sudo来运行一些特权命令，然而当我试图这么做时，我却得到了&quot;[我的用户名] is not in the sudoers file. This incident will be reported.&quot;的错误信息。我该怎么处理这种sudo错误呢？</p></blockquote><p>sudo是一个允许特定的用户组用另一个用户(典型的是root)的特权来运行一个命令。sudo有详细的日志功能，并且提供了对用户可通过sudo来运行哪些命令的细粒度控制。</p><h3 id="sudo-vs-su" tabindex="-1">Sudo vs. Su <a class="header-anchor" href="#sudo-vs-su" aria-label="Permalink to “Sudo vs. Su”">​</a></h3><p>su命令也提供了同样的特权提升功能，两者不同的是它们认证过程和特权变化的粒度。su允许你从你的登录会话切换到另一个用户的会话，然后你可以随心所欲地用该用户的特权来运行任何程序，但是你需要知道目标用户的密码才能切换这个用户。而另一方面，sudo能在单个命令的基础上工作，允许你用root的特权来运行单个命令。用sudo你不必一定要知道root的密码，但是在提示输入sudo密码的时候要输入你的密码。</p><h3 id="在sudoers列表里添加用户" tabindex="-1">在Sudoers列表里添加用户 <a class="header-anchor" href="#在sudoers列表里添加用户" aria-label="Permalink to “在Sudoers列表里添加用户”">​</a></h3><p>作为一个新用户的你如果试图运行sudo命令，你会碰到以下错误。意思是你不在这个包含经过认证就可以使用sudo特权的这么一个用户组的sudoers列表里。</p><pre><code>[my-user-id] is not in the sudoers file.  This incident will be reported.
</code></pre><p>有两个方法可以把你加入到sudoers列表中去。</p><h3 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h3><p>第一个方法是把你添加到名为sudo的Linux用户组里。这个特殊的Linux用户组是预配置来使用sudo的。因此，一旦你在这个组里面，那你就可以运行sudo命令了。</p><p>以下命令会把你加入到Linux的sudo组里，来确保让你能作为root用户来运行命令。</p><pre><code># adduser &lt;用户名&gt; sudo
</code></pre><p>现在来确认你的组员资格有没有更新，使用groups命令来看看你当前属于哪个组的列表里。这个列表必定是包含sudo组的。</p><pre><code>$ groups 
</code></pre><hr><pre><code>alice adm cdrom sudo dip plugdev fuse lpadmin netdev sambashare davfs2 libvirtd docker promiscuous
</code></pre><p>组员资格变动（和sudo访问）会在你登出后重新登录后生效。</p><h3 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to “方法二”">​</a></h3><p>第二个能让你使用sudo的方法是直接把你自己添加到 /etc/sudoers 这个配置文件中去。</p><p>要修改 /etc/sudoers 文件，你可以使用一个名为visudo的特殊sudo编辑器命令。用root身份简单调用以下命令。</p><pre><code># visudo 
</code></pre><p>这条命令能打开并编辑 /etc/sudoers 文件，将以下这行文字添加至文件末尾，并按Ctrl+X。提示出现时，保存修改退出。</p><pre><code>&lt;username&gt; ALL=(ALL) ALL
</code></pre><p>这个修改会立即生效，你就能马上使用sudo了。</p><p><img src="https://farm8.staticflickr.com/7511/15866443418_e147329e1b_c.jpg" alt=""></p><hr>`,27)),r("p",null,[e[1]||(e[1]=s("via: ",-1)),t(o,{href:"http://ask.xmodulo.com/fix-is-not-in-the-sudoers-file.html"},{default:i(()=>[...e[0]||(e[0]=[s("http://ask.xmodulo.com/fix-is-not-in-the-sudoers-file.html",-1)])]),_:1})]),r("p",null,[e[4]||(e[4]=s("译者：",-1)),t(o,{href:"https://github.com/ZTinoZ"},{default:i(()=>[...e[2]||(e[2]=[s("ZTinoZ",-1)])]),_:1}),e[5]||(e[5]=s(" 校对：",-1)),t(o,{href:"https://github.com/wxy"},{default:i(()=>[...e[3]||(e[3]=[s("wxy",-1)])]),_:1})]),r("p",null,[e[8]||(e[8]=s("本文由 ",-1)),t(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[6]||(e[6]=[s("LCTT",-1)])]),_:1}),e[9]||(e[9]=s(" 原创翻译，",-1)),t(o,{href:"http://linux.cn/"},{default:i(()=>[...e[7]||(e[7]=[s("Linux中国",-1)])]),_:1}),e[10]||(e[10]=s(" 荣誉推出",-1))])])}const b=n(p,[["render",f]]);export{c as __pageData,b as default};
